"""Functional comparison only; preserve every failed bounded search record."""
from pathlib import Path
import json,statistics
P=Path('research/batch54');inputs=json.loads((P/'remaining67-input-only.json').read_text())['cases'];baseline=json.loads((P/'baseline-saved67.json').read_text())['cases'];actual=json.loads(Path('reports/final-live-remaining67-batch54.json').read_text())['cases']
assert len(inputs)==len(baseline)==len(actual)==67
records=[]
for original,b,a in zip(inputs,baseline,actual):
    assert original['name']==b['name']==a['name'];h=a['helper'];w=a['whole'];old=b['whole'];assert 0<=h['work']<=16000000
    if w['returned']:assert w['valid'] and w['T']<=original['deadline_us'] and w['peak']<=original['hardware']['memory_limit'] and w['plan'] is not None
    else:assert not w['valid'] and w['plan'] is None and w['error']
    if h['valid']:assert h['T']<=original['deadline_us'] and h['peak']<=original['hardware']['memory_limit'] and len(h['order_ids'])==len(original['nodes']) and h['plan'] is not None
    records.append(dict(name=a['name'],partition=b['partition'],control=b['control'],before_whole_success=old['valid'],after_whole_success=w['valid'],before_T=old['T'],after_T=w['T'],before_peak=old['peak'],after_peak=w['peak'],whole_plan_equal=old['plan']==w['plan'],before_helper_success=b['helper']['valid'],after_helper_success=h['valid'],before_work=b['helper']['work'],after_work=h['work'],before_evaluations=b['helper']['evaluations'],after_evaluations=h['evaluations'],before_exhausted=b['helper']['exhausted'],after_exhausted=h['exhausted'],after_whole_error=w['error']))
summary=dict(status='ACTUAL_SINGLE67_FUNCTIONAL_COMPARISON',records=67,remaining=63,controls=4,before_legal=sum(r['before_whole_success'] for r in records),after_legal=sum(r['after_whole_success'] for r in records),restored=[r['name'] for r in records if not r['before_whole_success'] and r['after_whole_success']],lost=[r['name'] for r in records if r['before_whole_success'] and not r['after_whole_success']],common_quality_changes=[r for r in records if r['before_whole_success'] and r['after_whole_success'] and (r['before_T'],r['before_peak'])!=(r['after_T'],r['after_peak'])],failed_after=[r['name'] for r in records if not r['after_whole_success']],logical_work=dict(before_sum=sum(r['before_work'] for r in records),after_sum=sum(r['after_work'] for r in records),before_max=max(r['before_work'] for r in records),after_max=max(r['after_work'] for r in records),increased=sum(r['after_work']>r['before_work'] for r in records),decreased=sum(r['after_work']<r['before_work'] for r in records),equal=sum(r['after_work']==r['before_work'] for r in records)),comparisons=records,performance_unmeasured=True,default_changed=False,limits='Two C++ eventmodels checked every returned plan by actual driver;new recovery additionally requires independent root heap before acceptance. Historical saved R51 helper/full records are source-equivalent quality baselines,not matched timing trials.')
Path('reports/final-live-remaining67-summary-batch54.json').write_text(json.dumps(summary,indent=2)+'\n',encoding='utf-8');print(json.dumps({k:v for k,v in summary.items() if k!='comparisons'}),flush=True)
